function hash(s: string): number { let h = 5381; for (let i = 0; i < s.length; i++) h = (h * 33) ^ s.charCodeAt(i); return h >>> 0; }

/** Temaya (ya da temalara) göre havuz; karanlık kareler varsayılan olarak dışarıda. */
export function havuz(tema?: HavuzTema | HavuzTema[], { dikey, karanlik = false }: { dikey?: boolean; karanlik?: boolean } = {}): HavuzOge[] {
  const t = tema ? (Array.isArray(tema) ? tema : [tema]) : null;
  const l = MEDYA_HAVUZU.filter((o) => (!t || t.includes(o.tema)) && (karanlik || !o.karanlik) && (dikey === undefined || o.dikey === dikey));
  return l.length ? l : MEDYA_HAVUZU;
}

/** Tohumdan deterministik tek klip. */
export function havuzSec(tohum: string, tema?: HavuzTema | HavuzTema[], secenek?: { dikey?: boolean }): HavuzOge {
  const l = havuz(tema, secenek);
  return l[hash(tohum) % l.length];
}

/** Tema(lar)daki tüm durgun kareler (poster + ara kare). */
export function havuzGorselleri(tema?: HavuzTema | HavuzTema[]): string[] {
  return havuz(tema).flatMap((o) => [o.poster, o.kare]);
}
